  const hold = {
    id: 'hold_1',
    itemId: BOOK.id,
    memberId: ADA.id,
    pickupBranchId: 'central',
    placedOn: '2026-11-01',
    status: 'ready',
    readyOn: '2026-11-25',
  };
  const store = sampleStore({ holds: [hold] });
  const result = checkOutItem(store, { barcode: BOOK.barcode, memberId: ADA.id, today: TODAY });
